B.qE=s(["\u0b9e\u0bbe\u0baf\u0bbf.","\u0ba4\u0bbf\u0b99\u0bcd.","\u0b9a\u0bc6\u0bb5\u0bcd.","\u0baa\u0bc1\u0ba4.","\u0bb5\u0bbf\u0baf\u0bbe.","\u0bb5\u0bc6\u0bb3\u0bcd.","\u0b9a\u0ba9\u0bbf"],t.s)
B.a9a=s(['Al abrir la app por primera vez toca "Crear mi negocio".',"Ponle un nombre a tu negocio, tu correo y una contrase\xf1a.",'Un operador te entregar\xe1 un "c\xf3digo de activaci\xf3n". M\xe9telo para empezar a usar la app.',"Este tel\xe9fono queda como el due\xf1o del negocio."],t.s)
B.ajf=new A.dY(B.a9a,B.CH,"Primeros pasos")
B.a6O=s(["Al entrar ves un resumen de tu negocio: ventas, ganancias y caja del d\xeda.","El men\xfa inferior te lleva a las secciones principales: Resumen, Inventario, Vender, Caja y Ganancias.","El men\xfa (\u2630) de arriba a la izquierda abre todas las opciones del negocio.","El bot\xf3n flotante (FAB) abajo a la derecha te da acceso r\xe1pido a las acciones m\xe1s usadas: Inventario Diario, Publicar lista, Calculadora, Sincronizar y m\xe1s.",u.O],t.s)
B.ajr=new A.dY(B.a6O,B.wk,"La pantalla de inicio (Resumen)")
B.a9r=s(["Aqu\xed agregas los productos que vendes y su stock.","Ponles nombre, precio de compra y de venta, y categor\xeda.","Puedes organizar tu mercanc\xeda en almacenes y ver cu\xe1nto te queda de cada producto."],t.s)
B.aj4=new A.dY(B.a9r,B.ck,"Inventario")
B.a89=s(["Crea categor\xedas para organizar tus productos: Bebidas, Comestibles, Limpieza, etc.","Asigna cada producto a una categor\xeda para mantener el inventario ordenado.","Las categor\xedas aparecen al crear o editar un producto."],t.s)
B.ajm=new A.dY(B.a89,B.hk,"Categor\xedas de productos")
B.a9X=s(["Elige el producto, la cantidad y el m\xe9todo de pago.","Al vender, el stock se descuenta solo.","Cada venta queda guardada y aparece en Ganancias."],t.s)
B.aj2=new A.dY(B.a9X,B.mK,"Vender")
B.a9Q=s(["Revisa el resumen de ventas de cada d\xeda: ingresos, ganancias y unidades vendidas.","Toca un d\xeda para ver el detalle de cada venta realizada.","Puedes eliminar una venta desde aqu\xed si fue registrada por error (se devuelve el stock)."],t.s)
B.ajh=new A.dY(B.a9Q,B.ki,"Inventario Diario")
B.a69=s(["Sirve para hacer el arqueo de caja: cu\xe1nto dinero hay en el caj\xf3n.","Registra las monedas y billetes que hay y deja constancia de cada arqueo."],t.s)
B.aj9=new A.dY(B.a69,B.bB,"Caja")
B.a9E=s(["Registra todos los gastos del negocio: compras, servicios, salarios, etc.","As\xed las ganancias se calculan descontando lo que se gasta."],t.s)
B.ajo=new A.dY(B.a9E,B.wl,"Gastos")
B.abP=s(["Registra productos da\xf1ados, vencidos o perdidos.","Selecciona el producto, la cantidad y el motivo de la merma.","Las mermas quedan registradas para que tengas control de las p\xe9rdidas."],t.s)
B.ajc=new A.dY(B.abP,B.io,"Mermas")
B.a9e=s(["Registra tus cuentas bancarias o de pago m\xf3vil para recibir transferencias.","Ponles un alias, nombre del banco y n\xfamero de tarjeta.","Puedes subir una imagen del QR para que los clientes la vean al pagar.",'La cuenta marcada como predeterminada se muestra al seleccionar "Transferencia" como m\xe9todo de pago.'],t.s)
B.aj6=new A.dY(B.a9e,B.d7,"Cuentas de transferencia")
B.abU=s(['Cada vendedor usa la app "SSPV Ventas" en su propio tel\xe9fono.','En la pantalla de tu tel\xe9fono est\xe1 el "ID de este dispositivo": es la identidad de tu negocio.',"P\xeddele al vendedor el ID que muestra su app al abrirla y reg\xedstralo aqu\xed con su nombre.","Elige desde qu\xe9 punto de venta (almac\xe9n) vender\xe1.","Al quitar un vendedor, se elimina de tu tel\xe9fono y de la nube: su app dejar\xe1 de sincronizar con tu negocio."],t.s)
B.aj1=new A.dY(B.abU,B.CA,"Vendedores (dispositivos)")
B.aaT=s(["Organiza tu mercanc\xeda en varios lugares: almac\xe9n central, punto de venta, etc.","Haz traslados para mover stock de un lugar a otro."],t.s)
B.aja=new A.dY(B.aaT,B.wn,"Almacenes y traslados")
B.aaH=s([u.B,u.I,"Guarda un historial de los \xfaltimos c\xe1lculos realizados."],t.s)
B.aj5=new A.dY(B.aaH,B.kg,"Calculadora")
B.abm=s(["Sube tu inventario, ventas y gastos a la nube para tenerlos a salvo.",'Con "Sincronizar" tu informaci\xf3n viaja al servidor de respaldo.',"Sirve para que los vendedores bajen el inventario actualizado del negocio.","La app sincroniza sola cuando tiene internet."],t.s)
B.ajk=new A.dY(B.abm,B.mT,"Sincronizaci\xf3n en la nube")
B.aaF=s(["Comparte tu lista de precios con tus clientes por WhatsApp.","Personaliza la plantilla de publicaci\xf3n con el nombre del negocio, encabezado, pie de p\xe1gina y datos de contacto.","Vista previa en vivo para ver c\xf3mo quedar\xe1 el mensaje antes de compartirlo."],t.s)
B.aj3=new A.dY(B.aaF,B.mR,"Publicar en WhatsApp")
B.aa6=s(["Haz un backup para guardar una copia de todo tu negocio en el tel\xe9fono.","Si no tienes internet, comparte el inventario por WhatsApp y podr\xe1s importarlo donde necesites.","Puedes restaurar una copia si cambias de tel\xe9fono o pierdes datos."],t.s)
B.ajp=new A.dY(B.aa6,B.mI,"Respaldo de datos")
B.a9B=s(["Cambia los colores de la app y el modo claro u oscuro.","Configura la moneda por defecto (CUP, USD, EUR) y las tasas de cambio."],t.s)
